{
  "case_id": "xsu_sg_003_severity_assessment",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret nævner ikke den lægefagligt dokumenterede, individuelle helhedsvurdering af aktuelle symptomer. Det udelader behandling, effekt, restsymptomer/bivirkninger og rimelig medvirken samt sygdomshistorik (gentagelser, tilbagefald). Det tilføjer ukildede momenter: erhvervs-/uddannelsesdeltagelse som selvstændigt punkt, behov for hjælp og støtte, samt en 'funktionsvurdering'-metode. Det er væsentlige fejl og udeladelser."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Kun delvist dækket: funktionsnedsættelsens påvirkning af dagligt liv og delvist varighed. Mangler lægefagligt dokumenteret grundlag, behandling og effekt, restsymptomer/bivirkninger, medvirken i rimeligt omfang, gentagne sygdomsperioder og tilbagefaldsrisiko."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret forholder sig direkte til, hvad Udbetaling Danmark lægger vægt på ved sværhedsgraden, og er ikke fyldt med irrelevant tekst, selv om indholdet er upræcist."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledning."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så kildens gyldighed kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så støtten til påstandene kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer en 'særlig vurderingsmetode kaldet funktionsvurdering', som dækker fysisk, psykisk og social funktionsevne. Det har ingen støtte i materialet. Det tilføjer også behov for hjælp og støtte, deltagelse i uddannelse/arbejde som selvstændige vurderingsmomenter og andre faktorer som træthed og åndedrætsbesvær. Desuden hævder det, at UDK 'altid' søger en fair vurdering."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Svaret fremstiller en fast liste på 5 punkter og en bestemt metode, ikke illustrative eksempler ('f.eks.'/'blandt andet') i en samlet helhedsvurdering. Det fremhæver, at vurderingen er individuel, men markerer ikke, at momenterne er eksempler og ikke selvstændige betingelser. Det nævner ikke rimeligt omfang for medvirken."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er internt sammenhængende: det opregner momenter, nævner en metode og konkluderer, at vurderingen er individuel og kompleks. Der er ingen indre modsigelser."},
    "c10_legal_modality_precision": {"label": "not_met", "reason": "Svaret præsenterer momenter og metoden som faste ('lægger vægt på følgende', 'bruger også en særlig metode') og siger, at UDK 'altid' søger en fair vurdering. Det giver et udtømmende og mere absolut indtryk end kildens eksempler ('f.eks.')."}
  },
  "xhaile_coverage": {
    "A14": {"label": "no", "reason": "Svaret kræver ikke, at funktionsnedsættelsen er velbeskrevet og lægefagligt dokumenteret, og nævner ikke lægefaglige oplysninger eller journaler. Det dækker kun dagligt funktionsniveau og varighed, ikke behandling, restsymptomer eller tilbagefald."}
  },
  "overall_notes": "Svaret er generisk og uden kilder. Det rammer delvist påvirkning af dagligt liv og varighed, men udelader den lægefaglige dokumentation, behandling/effekt/restsymptomer/medvirken og tilbagefaldsrisiko. Det tilføjer ukildede elementer, især 'funktionsvurdering' og erhvervs-/uddannelsesdeltagelse samt behov for hjælp."
}

